-- ASSERT: SELECT in_picker FROM countries WHERE code = 'GH' = 1
-- ASSERT: SELECT roi_complexity FROM countries WHERE code = 'GH' = 'complex'
-- ASSERT: SELECT eu_member FROM countries WHERE code = 'GH' = 0
-- ASSERT: SELECT count(*) FROM country_translations WHERE country_id = (SELECT id FROM countries WHERE code = 'GH') = 4
